258	bool encode_to_der(X509* cert, std::vector<unsigned char>& der) {
259	    int length = i2d_X509(cert, nullptr);
260	    if (length <= 0) return false;
261	    der.resize(static_cast<size_t>(length));
262	    unsigned char* pointer = der.data();
263	    int encoded = i2d_X509(cert, &pointer);
264	    return encoded == length &&
265	           pointer == der.data() + der.size();
